-- NFL runs by season: count, yards, before contact, box count, blitz share
rsql select lp.season, count(*) runs, round(avg(json_extract(j.value,'$.yards')),3) yards, round(avg(json_extract(j.value,'$.before_contact')),3) ybc, round(avg(json_extract(j.value,'$.box_count')),3) box, round(avg(json_extract(j.value,'$.blitz')),4) blitz, round(avg(json_extract(j.value,'$.yardline_100')),1) yl, round(avg(json_extract(j.value,'$.togo')),2) togo from log_plays lp, json_each(more('log_plays', lp._more), '$.plays') j where lp.stream = 'nfl' and json_extract(j.value,'$.kind') = 'Run' group by lp.season order by lp.season
-- NFL runs by call, early (2026-28) vs late (2032-35): share and yards
rsql select json_extract(j.value,'$.call') callname, case when lp.season <= 2028 then 'early' when lp.season >= 2032 then 'late' else 'mid' end per, count(*) n, round(avg(json_extract(j.value,'$.yards')),3) yards, round(avg(json_extract(j.value,'$.before_contact')),3) ybc from log_plays lp, json_each(more('log_plays', lp._more), '$.plays') j where lp.stream = 'nfl' and lp.season >= 2026 and json_extract(j.value,'$.kind') = 'Run' group by callname, per order by callname, per
-- NFL runs by box count, early vs late
rsql select json_extract(j.value,'$.box_count') box, case when lp.season <= 2028 then 'early' when lp.season >= 2032 then 'late' else 'mid' end per, count(*) n, round(avg(json_extract(j.value,'$.yards')),3) yards, round(avg(json_extract(j.value,'$.before_contact')),3) ybc from log_plays lp, json_each(more('log_plays', lp._more), '$.plays') j where lp.stream = 'nfl' and lp.season >= 2026 and json_extract(j.value,'$.kind') = 'Run' group by box, per order by box, per
-- NFL runs by defense call, early vs late
rsql select json_extract(j.value,'$.defense_call') dcall, case when lp.season <= 2028 then 'early' when lp.season >= 2032 then 'late' else 'mid' end per, count(*) n, round(avg(json_extract(j.value,'$.yards')),3) yards, round(avg(json_extract(j.value,'$.before_contact')),3) ybc from log_plays lp, json_each(more('log_plays', lp._more), '$.plays') j where lp.stream = 'nfl' and lp.season >= 2026 and json_extract(j.value,'$.kind') = 'Run' group by dcall, per having n > 300 order by dcall, per
-- NFL runs by personnel, early vs late
rsql select json_extract(j.value,'$.personnel') pers, case when lp.season <= 2028 then 'early' when lp.season >= 2032 then 'late' else 'mid' end per, count(*) n, round(avg(json_extract(j.value,'$.yards')),3) yards from log_plays lp, json_each(more('log_plays', lp._more), '$.plays') j where lp.stream = 'nfl' and lp.season >= 2026 and json_extract(j.value,'$.kind') = 'Run' group by pers, per having n > 300 order by pers, per
